using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using HarborValeGreybox.Workshop;
using HarborValeGreybox.Driving;
namespace HarborValeGreybox.Racing.Editor {
public static class LineupVerification {
 static readonly List<string> checks=new List<string>();static void Check(bool yes,string text){checks.Add((yes?"PASS ":"FAIL ")+text);if(!yes)throw new Exception(text);}static void Reject(Action a,string text){bool fail=false;try{a();}catch{fail=true;}Check(fail,text);}
 static TrialSession Complete(TrialDefinition d){var s=new TrialSession(d);s.Tick(4,Vector3.zero,Vector3.zero);s.Tick(90,Vector3.zero,Vector3.zero);foreach(var g in d.checkpoints)s.Tick(.02f,g.Position-g.Forward,g.Position+g.Forward);return s;}
 static DuelRaceSession Win(DuelContract d,TrialDefinition route){var s=new DuelRaceSession(d,route);s.Tick(4,Vector3.zero,Vector3.zero,Vector3.zero,Vector3.zero);foreach(var g in route.checkpoints)s.Tick(.02f,g.Position-g.Forward,g.Position+g.Forward,Vector3.zero,Vector3.zero);return s;}
 public static void Run(){Directory.CreateDirectory("Verification/Lineup");try{LineupAssets.Build();Check(VehicleLineup.All.Length==3,"Three original distinct model profiles imported");var route=JsonUtility.FromJson<TrialDefinition>(Resources.Load<TextAsset>("FirstDocksideTrial").text);string folder=Path.GetFullPath("Verification/Lineup/profiles/"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string file=folder+"/v8.json",old=Path.GetFullPath("Verification/Lineup/fixtures/released-v7.json"),oldBytes=File.ReadAllText(old);var before=JsonUtility.FromJson<RaceProgress>(oldBytes);var store=new RaceProgressStore(file,route,lineupLegacyFile:old);Check(store.Profile.version==8&&store.Profile.profileId==before.profileId&&store.Profile.availableCredits==before.availableCredits&&JsonUtility.ToJson(store.Profile.spending)==JsonUtility.ToJson(before.spending),"Real released v7 imports once preserving balances, identities and immutable receipts");Check(File.ReadAllText(old)==oldBytes&&store.Profile.fleet.cars.All(c=>c.modelId=="car_finch"),"Old file stays byte-identical; existing original/rival/replacement cars remain Finch");for(int i=0;i<100;i++)store.Settle(Complete(route),out _);string original=JsonUtility.ToJson(store.Profile.workshop);var owned=new List<string>();
 foreach(var spec in VehicleLineup.All){var c=WorkshopCatalog.Load(spec.id);var d=c.Resolve(new WorkshopBuild());Check(d.carId==spec.id&&d.massKg==spec.mass&&d.ratios.Length==6&&d.torque.SequenceEqual(spec.workshop.stock.torque),"Actual stock engine/mass/gearing use "+spec.name+" authored specs");Check(FitmentTuning.Drive(c,new WorkshopBuild())==spec.stockDrive,"Factory drivetrain is "+spec.stockDrive+" for "+spec.name);string request=Guid.NewGuid().ToString("N");int cash=store.Profile.availableCredits;Reject(()=>store.BuyVehicle(request,spec.id,spec.price-1),"Changed "+spec.name+" quote rejected");store.BuyVehicle(request,spec.id,spec.price);store.BuyVehicle(request,spec.id,spec.price);owned.Add(store.Profile.fleet.selectedId);Check(store.Profile.availableCredits==cash-spec.price&&store.ActiveModelId==spec.id,"Atomic model purchase creates identity, selects car and charges once: "+spec.name);var target=c.Find("induction_small_1");foreach(var part in c.MissingPath(store.ActiveWorkshop,target))store.PurchaseWorkshop(Guid.NewGuid().ToString("N"),part.id,c.Price(store.ActiveWorkshop,part),out _);Check(c.Resolve(store.ActiveWorkshop).carId==spec.id&&c.Resolve(store.ActiveWorkshop).PeakKw()>d.PeakKw(),"Sequential paid hardware installs actual matched boost curve on "+spec.name);Check(JsonUtility.ToJson(store.Profile.workshop)==original,"Other car purchase/tune does not overwrite original paid Finch build");}
 var reloaded=new RaceProgressStore(file,route);Check(reloaded.ActiveModelId=="car_bastion"&&owned.All(id=>FleetLedger.Find(reloaded.Profile.fleet,id).owner=="player"),"Every distinct owned model/build replays after reload");reloaded.SelectVehicle(Guid.NewGuid().ToString("N"),owned[0]);Check(reloaded.ActiveModelId=="car_coda"&&reloaded.ActiveWorkshop.induction=="small","Selecting earlier coupe restores its own previously purchased turbo build");var pink=reloaded.BeginDuel(Guid.NewGuid().ToString("N"),"tuned","pinks");Check(pink.playerModelId=="car_coda"&&pink.opponentModelId=="car_vector","Title contract freezes actual player/rival model identities");reloaded.SettleDuel(Win(pink,route));Check(FleetLedger.Find(reloaded.Profile.fleet,pink.opponentId).modelId=="car_vector","Pink win transfers actual sedan model/build rather than a renamed Finch");string frozen=File.ReadAllText(file);var failure=new RaceProgressStore(file,route,()=>{throw new IOException("Injected failure");});Reject(()=>failure.BuyVehicle(Guid.NewGuid().ToString("N"),"car_coda",4500),"Failed vehicle commit reports failure");Check(File.ReadAllText(file)==frozen,"Failed commit preserves previous cash, fleet and builds");var fake=JsonUtility.FromJson<RaceProgress>(frozen);fake.fleet.cars[0].modelId="car_bastion";string bad=folder+"/bad.json";File.WriteAllText(bad,JsonUtility.ToJson(fake));Reject(()=>new RaceProgressStore(bad,route),"Forged model cache cannot change an old owned car");fake=JsonUtility.FromJson<RaceProgress>(frozen);fake.version=9;File.WriteAllText(bad,JsonUtility.ToJson(fake));File.WriteAllText(bad+".bak",frozen);Reject(()=>new RaceProgressStore(bad,route),"Unknown future9 preserves file rather than restoring older backup");Check(File.ReadAllText(old)==oldBytes,"All new purchases leave v7 source untouched");Geometry();Audio();File.WriteAllLines("Verification/Lineup/rules.txt",checks);
 }catch(Exception e){checks.Add("FAIL "+e);File.WriteAllLines("Verification/Lineup/rules.txt",checks);throw;}}
 public static void Geometry(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.position=new Vector3(0,-.5f,0);floor.transform.localScale=new Vector3(100,1,2200);var previous=Physics.simulationMode;Physics.simulationMode=SimulationMode.Script;try{var values=new List<string>();foreach(var spec in VehicleLineup.All){var car=TrafficWorld.CreateCar(spec.name,new WorkshopBuild(),-1,spec.id);car.ResetAt(new Vector3(0,.35f,-800),Quaternion.identity);car.externalInput=true;car.commandedHandbrake=false;for(int i=0;i<100;i++){car.Tick(.02f);Physics.Simulate(.02f);}Check(car.GetComponentsInChildren<WheelCollider>().Length==4&&Math.Abs(car.Wheels[0].transform.localPosition.z-spec.wheelBase/2)<.001&&Math.Abs(car.Wheels[0].radius-spec.wheelRadius)<.001,"Four physical contacts match "+spec.name+" wheelbase/radius");Check(car.Engine.definition.massKg==spec.mass&&car.driveLabel==spec.stockDrive.ToUpperInvariant(),"Physical mass and driven axles match "+spec.name);float elapsed=0;car.commandedPedal=1;car.commandedServiceBrake=0;for(int i=0;i<1500&&car.SpeedKph<100;i++){car.Tick(.02f);Physics.Simulate(.02f);elapsed+=.02f;}Check(car.SpeedKph>=100,"Actual "+spec.name+" reaches100km/h using own wheel torque");values.Add(spec.name+" / measured 0–100≈"+elapsed.ToString("F2")+"s / mass="+car.Body.mass+" / drive="+car.driveLabel);UnityEngine.Object.DestroyImmediate(car.gameObject);}File.WriteAllLines("Verification/Lineup/acceleration.txt",values);}finally{Physics.simulationMode=previous;UnityEngine.Object.DestroyImmediate(floor);}var prefab=Resources.Load<GameObject>("PhysicalGarage");var garage=UnityEngine.Object.Instantiate(prefab);Physics.SyncTransforms();for(int i=-1;i<=1;i++){bool blocked=Physics.BoxCast(new Vector3(i*5.8f,1,-12),new Vector3(1,.65f,2.5f),Vector3.forward,out _,Quaternion.identity,12);Check(!blocked,"Physical garage bay "+(i+2)+" admits full-size car through open doorway");}Check(garage.GetComponentsInChildren<BoxCollider>().Length>10,"Garage walls and workshop props are actual collision geometry");UnityEngine.Object.DestroyImmediate(garage);}
 static void Audio(){foreach(int cylinders in new[]{4,6,8}){var dsp=new DrivingAudioDsp(48000);double energy=0;for(int i=0;i<48000;i++){float x=dsp.Sample(200,.15f,0,0,0,0,1,1,false,0,0,.8f,0,cylinders);if(float.IsNaN(x)||Math.Abs(x)>.721f)throw new Exception("Invalid cylinder audio");energy+=x*x;}Check(energy>1,"Bounded, audible "+cylinders+"-cylinder combustion synthesis");}}
 public static void Release(){Run();HarborValeGreybox.Workshop.Editor.AvCameraVerification.Run();HarborValeGreybox.Workshop.Editor.TurboAudioVerification.Run();HarborValeGreybox.Presentation.Editor.CityArtVerification.Release();}
}
}
